SettingsPresentation::SettingsPresentation(core::Module module,SettingsController&controller,std::vector<SettingsIcon>icons,SettingsAbout about,SettingsViewHooks hooks):module_(module),controller_(&controller),icons_(std::move(icons)),about_(std::move(about)),hooks_(std::move(hooks)){
    need(module==core::Module::system||module==core::Module::display||module==core::Module::hotkeys||module==core::Module::about,"Invalid Settings module");need(icons_.size()<=256&&about_.credits.size()<=64,"Settings metadata exceeds source UI bound");
    for(std::size_t n=0;n<icons_.size();++n){need(!icons_[n].id.empty()&&icons_[n].id.size()<256&&Json::validUtf8(icons_[n].title),"Invalid explicit icon roster");for(std::size_t k=0;k<n;++k)need(icons_[n].id!=icons_[k].id,"Duplicate Settings icon identity");}
    if(module==core::Module::system&&hooks_.displays)displays_=hooks_.displays();rebuild();
}
