 chrome.add(label("settings.heading",{12,1,306,23},view.heading,16,primary,a.scale,"semibold"));chrome.add(solid("settings.headerLine",{12,29,376,1},alpha(a.accent,.5)));if(view.page!=SettingsPage::main)chrome.button("back",view.back,{323,2,65,25},false,a.accent,primary,muted,a.scale);
