   case Kind::toggle:b.add(shape(id+"/track",{324,rect.y+10,50,20},3,alpha(r.selected?a.accent:muted,r.selected?.24:.12),r.selected?a.accent:alpha(muted,.5),.7));b.feedback(r.id,{321,rect.y+7,56,26},a.accent);b.add(solid(id+"/marker",{r.selected?350.:328.,rect.y+14,20,12},r.selected?a.accent:muted));b.add(label(id+"/value",{270,rect.y+13,42,15},r.selected?"ON":"OFF",9,r.selected?a.accent:muted,a.scale,"regular","right"));break;
