   case Kind::slider:{need(std::isfinite(r.number)&&std::isfinite(r.minimum)&&std::isfinite(r.maximum)&&r.maximum>r.minimum,"Invalid Settings slider");std::string value;for(const auto&s:view.sliders)if(s.id==r.id)value=s.formatted;if(value.empty())value=r.value;need(!value.empty(),"Settings slider requires preformatted caller value");b.add(label(id+"/value",{20,rect.y+26,167,13},value,8.5,muted,a.scale));const auto fraction=std::clamp((r.number-r.minimum)/(r.maximum-r.minimum),0.,1.);b.add(solid(id+"/track",{198,rect.y+20.5,172,2},alpha(muted,.3)));b.add(solid(id+"/fill",{198,rect.y+20.5,172*fraction,2},a.accent));b.add(shape(id+"/handle",{194+172*fraction,rect.y+14.5,8,14},2,a.accent));break;}
